<?php declare(strict_types=1);namespace NpmGateway\Notifications;use NpmGateway\Contracts\MarketingFlyerNotifierInterface;use NpmGateway\Services\HrEmployeeNotificationConfig;use NpmGateway\Support\GatewayDateTimeFormatter;use NpmGateway\ValueObjects\GatewayEmailMessage;use PHPMailer\PHPMailer\PHPMailer;
final class MarketingFlyerEmailSender implements MarketingFlyerNotifierInterface{private readonly GatewayEmailRenderer$renderer;public function __construct(private readonly array$config,private readonly?\Closure$factory=null,?GatewayEmailRenderer$renderer=null){$this->renderer=$renderer??new GatewayEmailRenderer();}public function send(array$f,array$recipients,string$unusedPath=''):array{$targets=array_values(array_unique(array_filter(array_map('strtolower',$recipients),fn($email)=>filter_var($email,FILTER_VALIDATE_EMAIL)!==false)));if(($this->config['test_mode']??false)===true){$test=strtolower(trim((string)($this->config['test_email']??'')));if(filter_var($test,FILTER_VALIDATE_EMAIL)===false)return['sent'=>0,'failed'=>count($targets),'warning'=>'Test-mode email is missing or invalid.'];$targets=[$test];}$smtp=HrEmployeeNotificationConfig::fromArray((array)$this->config['smtp']);$month=date('F Y',strtotime((string)$f['flyer_month']));$promo=$f['flyer_type']==='promo'?' Promo':'';$title=$month.$promo.' Flyer';$subject=$title." \u{2014} ".$f['property_name'];$corporate=($this->config['test_mode']??false)===true;$path=$corporate?'/corporate/marketing/flyers/'.$f['public_id'].'/download':'/community-actions/'.$f['property_slug'].'/flyers/'.$f['public_id'].'/download';$url=rtrim((string)$this->config['app_url'],'/').$path;$content=$this->renderer->render(new GatewayEmailMessage('A Marketing flyer is available in Gateway.','MARKETING',$title,(string)$f['property_name'],null,'neutral',[['label'=>'Property','value'=>(string)$f['property_name'],'emphasized'=>true],['label'=>'Flyer Month','value'=>$month],['label'=>'Flyer Type','value'=>ucfirst((string)$f['flyer_type'])],['label'=>'Uploaded By','value'=>(string)$f['uploaded_by_name']],['label'=>'Uploaded At','value'=>GatewayDateTimeFormatter::format((string)$f['updated_at'])]],[],'Download Flyer',$url));$sent=0;$failed=0;foreach($targets as$email)try{$mail=$this->factory?($this->factory)():new PHPMailer(true);$mail->isSMTP()